import { Sky as DreiSky, Stars } from '@react-three/drei'
import { useFrame } from '@react-three/fiber'
import { lazyModule, useNodeRenderer, useSun, type Vec3 } from '@runek/core'
import { useEffect, useMemo } from 'react'

// The WebGPU (TSL) twins of drei's Sky and Stars, loaded only under a node renderer.
const skyNodes = lazyModule(() => import('./nodes/sky'))
type SkyNodes = Awaited<ReturnType<typeof skyNodes>>

export interface SkyProps {
  /** Accepted for the component contract; this component has no seeded variation yet. */
  seed?: number
  /** Direction of the sun; also where the bright spot appears. Set this to pin the
   *  sky to a fixed sun and bypass the world's day/night cycle. */
  sunPosition?: Vec3
  turbidity?: number
  rayleigh?: number
  /** Background when the sun is below the horizon. */
  nightColor?: string
}

/**
 * Procedural atmospheric sky (no textures). With no explicit `sunPosition` it
 * follows the world's time-of-day (`<World time>` / `timezone`): the sun arcs
 * overhead by day, and at night the dome swaps to a dark sky with a procedural
 * starfield. Pass `sunPosition` to pin a fixed sun and opt out of the cycle.
 */
export function Sky({
  sunPosition,
  turbidity = 8,
  rayleigh = 1.4,
  nightColor = '#04060e',
}: SkyProps) {
  const sun = useSun()
  const nodes = useNodeRenderer() ? skyNodes() : null
  if (nodes) {
    const position = sunPosition ?? sun.position
    if (!sunPosition && !sun.day) return <NodeStars nodes={nodes} nightColor={nightColor} />
    return <NodeSky nodes={nodes} sun={position} turbidity={turbidity} rayleigh={rayleigh} />
  }
  if (sunPosition) {
    return <DreiSky sunPosition={sunPosition} turbidity={turbidity} rayleigh={rayleigh} />
  }

  if (!sun.day) {
    return (
      <>
        <color attach="background" args={[nightColor]} />
        <Stars radius={80} depth={50} count={2500} factor={4} saturation={0} fade speed={0.4} />
      </>
    )
  }
  return <DreiSky sunPosition={sun.position} turbidity={turbidity} rayleigh={rayleigh} />
}

function NodeSky({
  nodes,
  sun,
  turbidity,
  rayleigh,
}: {
  nodes: SkyNodes
  sun: Vec3
  turbidity: number
  rayleigh: number
}) {
  const sky = useMemo(() => nodes.skyMesh(), [nodes])
  useEffect(() => () => (sky.material as { dispose(): void }).dispose(), [sky])
  sky.turbidity.value = turbidity
  sky.rayleigh.value = rayleigh
  sky.sunPosition.value.set(...sun)
  return <primitive object={sky} />
}

function NodeStars({ nodes, nightColor }: { nodes: SkyNodes; nightColor: string }) {
  const stars = useMemo(
    () => nodes.starField({ radius: 80, depth: 50, count: 2500, factor: 4, fade: true }),
    [nodes],
  )
  useEffect(() => () => stars.dispose(), [stars])
  useFrame(({ clock }) => {
    stars.time.value = clock.elapsedTime * 0.4
  })
  return (
    <>
      <color attach="background" args={[nightColor]} />
      <primitive object={stars.mesh} />
    </>
  )
}

// Mounted wherever the viewer is when a world streams.
Sky.stream = false

import { rng } from '@runek/core'
import {
  AdditiveBlending,
  Color,
  InstancedBufferAttribute,
  type Mesh,
  Spherical,
  Vector3,
} from 'three'
import { SkyMesh } from 'three/addons/objects/SkyMesh.js'
import {
  attribute,
  cameraProjectionMatrix,
  distance,
  exp,
  float,
  modelViewMatrix,
  positionGeometry,
  sin,
  uv,
  varying,
  vec2,
  vec4,
  viewportSize,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node, Mesh as NodeMesh } from 'three/webgpu'
import { pointQuads } from './portal'
import { follow } from './uniforms'

type F = Node<'float'>

/** The node (TSL) twin of drei's `Sky`: three's own `SkyMesh`, clouds off, at drei's size. */
export function skyMesh(scale = 1000) {
  const sky = new SkyMesh()
  sky.scale.setScalar(scale)
  sky.cloudCoverage.value = 0
  sky.mieCoefficient.value = 0.005
  sky.mieDirectionalG.value = 0.8
  return sky
}

export interface StarField {
  mesh: Mesh
  time: { value: number }
  dispose(): void
}

/**
 * The node (TSL) twin of drei's `Stars` (same shell of stars, sizes and twinkle), drawn as
 * instanced quads since WebGPU draws points a pixel wide. Seeded, where drei's are random.
 */
export function starField({
  radius = 100,
  depth = 50,
  count = 5000,
  factor = 4,
  saturation = 0,
  fade = false,
  seed = 1,
}): StarField {
  const random = rng(seed)
  const positions = new Float32Array(count * 3)
  const colors = new Float32Array(count * 3)
  const sizes = new Float32Array(count)
  const at = new Vector3()
  const color = new Color()
  let r = radius + depth
  const increment = depth / count
  for (let i = 0; i < count; i++) {
    r -= increment * random()
    at.setFromSpherical(new Spherical(r, Math.acos(1 - random() * 2), random() * 2 * Math.PI))
    at.toArray(positions, i * 3)
    color.setHSL(i / count, saturation, 0.9)
    color.toArray(colors, i * 3)
    sizes[i] = (0.5 + 0.5 * random()) * factor
  }
  const geometry = pointQuads(count, {
    aStar: new InstancedBufferAttribute(positions, 3),
    aColor: new InstancedBufferAttribute(colors, 3),
    aSize: new InstancedBufferAttribute(sizes, 1),
  })

  const time = { value: 0 }
  const t = follow<F>(time)
  // As drei: the star sits at its position with w = 0.5 (twice as far, before the divide), and
  // its size in pixels shrinks with depth and breathes with time.
  const view = modelViewMatrix.mul(vec4(attribute('aStar', 'vec3') as Node<'vec3'>, 0.5))
  const size = (attribute('aSize', 'float') as F)
    .mul(float(30).div(view.z.negate()))
    .mul(sin(t.add(100)).add(3))
  const clip = cameraProjectionMatrix.mul(view)
  const offset = positionGeometry.xy.mul(size).div(viewportSize.div(2)).mul(clip.w)
  const tint = varying(attribute('aColor', 'vec3')) as Node<'vec3'>
  const d = distance(uv(), vec2(0.5))
  const opacity = fade ? float(1).div(exp(d.sub(0.25).mul(16)).add(1)) : float(1)

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  material.vertexNode = clip.add(vec4(offset, 0, 0))
  material.colorNode = vec4(tint, opacity)
  const mesh = new NodeMesh(geometry, material)
  mesh.frustumCulled = false
  return {
    mesh,
    time,
    dispose() {
      geometry.dispose()
      material.dispose()
    },
  }
}

import {
  AdditiveBlending,
  type BufferGeometry,
  type Color,
  type InstancedBufferAttribute,
  InstancedBufferGeometry,
  PlaneGeometry,
} from 'three'
import {
  attribute,
  cameraProjectionMatrix,
  clamp,
  cos,
  exp,
  float,
  fract,
  length,
  max,
  mix,
  modelViewMatrix,
  positionGeometry,
  pow,
  sin,
  smoothstep,
  uv,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { fbm } from './noise'
import { follow } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>

/** A point `offset` (in view units) from the object's center, facing the camera: the clip
 *  position the GLSL computes as `projectionMatrix * (modelViewMatrix * origin + offset)`. */
export function facing(offset: V2) {
  const center = modelViewMatrix.mul(vec4(0, 0, 0, 1))
  return cameraProjectionMatrix.mul(center.add(vec4(offset, 0, 0)))
}

/** Rotate `p` by an angle growing toward the center: noise sampled through it spirals. */
function twirl(p: V2, r: F, k: number, t: F): V2 {
  const a = float(k).div(r.add(0.15)).add(t)
  const c = cos(a)
  const s = sin(a)
  return vec2(c.mul(p.x).add(s.mul(p.y)), s.negate().mul(p.x).add(c.mul(p.y))) as V2
}

export interface VortexUniforms {
  uTime: { value: number }
  uR: { value: number }
  uExtent: { value: number }
  uSeed: { value: number }
  uHot: { value: Color }
  uCool: { value: Color }
}

/** The node (TSL) twin of `Portal`'s vortex. */
export function vortexMaterial(record: VortexUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const extent = follow<F>(record.uExtent)
  const seed = follow<F>(record.uSeed)
  const hot = follow<V3>(record.uHot)
  const cool = follow<V3>(record.uCool)

  const p = varying(positionGeometry.xy.mul(extent)) as V2
  const r = length(p) as F
  const h = 0.42
  let arms = mix(
    fbm(twirl(p, r, 2.2, time.mul(0.7)).mul(2.4).add(seed) as V2, 4, 2.03, 17.1),
    fbm(twirl(p, r, 3.6, time.mul(1.4)).mul(4.2).sub(seed) as V2, 4, 2.03, 17.1),
    0.45,
  ) as F
  arms = smoothstep(0.3, 0.85, arms) as F
  const outside = smoothstep(h - 0.012, h + 0.012, r)
  const disc = outside.mul(exp(r.sub(h).mul(-2.4))).mul(smoothstep(0.95, 1.3, r).oneMinus())
  const ring = exp(pow(r.sub(h * 1.04).div(0.022), 2).negate())
  const halo = outside.mul(exp(r.sub(h).mul(-1.7))).mul(smoothstep(1.3, 1.9, r).oneMinus())
  const pulse = sin(time.mul(1.3).add(r.mul(6)))
    .mul(0.15)
    .add(0.85)
  const heat = exp(r.sub(h).mul(-5))
  const tint = mix(cool, hot, clamp(heat, 0, 1)) as V3
  let light = tint
    .mul(disc.mul(arms).mul(3).add(halo.mul(0.4).mul(pulse)))
    .add(mix(hot, vec3(1), 0.6).mul(ring).mul(1.6)) as V3
  const inner = outside
    .oneMinus()
    .mul(pow(r.div(h), 6))
    .mul(arms)
    .mul(0.25)
  light = light.add(cool.mul(inner)) as V3
  const shadow = smoothstep(h, h * 1.8, r)
    .oneMinus()
    .mul(0.6)
  const alpha = max(
    outside.oneMinus(),
    clamp(disc.mul(arms).mul(0.7).add(shadow.mul(outside)), 0, 0.95),
  )

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    premultipliedAlpha: true,
    depthWrite: false,
  })
  material.vertexNode = facing(positionGeometry.xy.mul(extent).mul(R) as V2)
  // Light added over the scene: the GLSL adds it to display values, this to linear light, so it
  // goes in as is (converting it would wash the swirl out against a bright sky).
  material.colorNode = vec4(light, alpha)
  material.toneMapped = false
  return material
}

/**
 * Sized points for `WebGPURenderer`, which draws `Points` one pixel wide: one camera-facing quad
 * per point, instanced. `attributes` become per-instance attributes of the same names.
 */
export function pointQuads(count: number, attributes: Record<string, InstancedBufferAttribute>) {
  const quad = new PlaneGeometry(1, 1)
  const geometry = new InstancedBufferGeometry()
  geometry.index = quad.index
  geometry.setAttribute('position', quad.getAttribute('position'))
  geometry.setAttribute('uv', quad.getAttribute('uv'))
  for (const [name, attr] of Object.entries(attributes)) geometry.setAttribute(name, attr)
  geometry.instanceCount = count
  return geometry as BufferGeometry
}

export interface PortalMoteUniforms {
  uTime: { value: number }
  uR: { value: number }
  uSize: { value: number }
  uColor: { value: Color }
}

/** The node (TSL) twin of `Portal`'s drifting motes, drawn on `pointQuads`. */
export function portalMotesMaterial(record: PortalMoteUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const size = follow<F>(record.uSize)
  const color = follow<V3>(record.uColor)
  const mote = attribute('aMote', 'vec3') as V3
  const life = fract(mote.y.add(time.mul(mote.z))) as F
  const r = mix(1.45, 0.44, life.mul(life)) as F
  const a = mote.x.sub(float(2.2).div(r.add(0.15))).sub(time.mul(0.7))
  const span = size.mul(life.add(0.6))
  const offset = vec2(cos(a), sin(a)).mul(r).mul(R).add(positionGeometry.xy.mul(span)) as V2
  const fade = varying(smoothstep(0, 0.25, life).mul(smoothstep(0.85, 1, life).oneMinus())) as F
  const d = length(uv().sub(0.5))

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  material.vertexNode = facing(offset)
  material.colorNode = vec4(color.mul(smoothstep(0.5, 0, d)).mul(fade), 1)
  material.toneMapped = false
  return material
}

/** The node (TSL) twin of a portal's or rift's glow pooled on the ground. */
export function poolMaterial(
  record: { uColor: { value: Color }; uOpen?: { value: number } },
  strength: number,
) {
  const color = follow<V3>(record.uColor)
  const open = record.uOpen ? follow<F>(record.uOpen) : float(1)
  const r = length(uv().sub(0.5)).mul(2)
  const a = pow(max(r.oneMinus(), 0), 2.2).mul(strength).mul(open)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  // Added over the floor in linear light, as is (see the vortex).
  material.colorNode = vec4(color.mul(a), 1)
  material.toneMapped = false
  return material
}

import { dot, float, floor, fract, mix, sin, vec2 } from 'three/tsl'
import type { Node } from 'three/webgpu'

type V2 = Node<'vec2'>
type F = Node<'float'>

/** The GLSL `hash` the shader components share: a pseudo-random 0..1 per point. */
export function hash(p: V2): F {
  return fract(sin(dot(p, vec2(127.1, 311.7))).mul(43758.5453)) as F
}

/** Smooth value noise, 0..1. */
export function noise(p: V2): F {
  const i = floor(p) as V2
  const f = fract(p) as V2
  const u = f.mul(f).mul(f.mul(-2).add(3)) as V2
  const a = hash(i)
  const b = hash(i.add(vec2(1, 0)) as V2)
  const c = hash(i.add(vec2(0, 1)) as V2)
  const d = hash(i.add(vec2(1, 1)) as V2)
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) as F
}

/** Fractal noise: `octaves` layers, each `lacunarity` times finer and shifted by `shift`. */
export function fbm(p: V2, octaves: number, lacunarity: number, shift: number): F {
  let v: F = float(0)
  let q: V2 = p
  let a = 0.5
  for (let i = 0; i < octaves; i++) {
    v = v.add(noise(q).mul(a)) as F
    q = q.mul(lacunarity).add(shift) as V2
    a *= 0.5
  }
  return v
}

import { uniform } from 'three/tsl'
import type { Node } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}
